import sharp from "sharp";
import outlines from "../../src/lib/print/glyphs/geist.json";

// Real QR for "INSIDE914 LOCAL TEST", generated by Core Image's QRCodeGenerator (M).
// Fixed text matrix keeps the fixture portable without a QR runtime dependency.
const qr = [
  "00000000000000000000000",
  "01111111000100011111110",
  "01000001000100010000010",
  "01011101011101010111010",
  "01011101010101010111010",
  "01011101010001010111010",
  "01000001011101010000010",
  "01111111010101011111110",
  "00000000011000000000000",
  "01011111000001011111000",
  "00001010010011010100100",
  "00001011010101100011000",
  "01111000001000001010000",
  "00000101010100011110100",
  "00000000011010010010110",
  "01111111001011000101000",
  "01000001011100011000010",
  "01011101010101101011010",
  "01011101011011010111000",
  "01011101011010101111000",
  "01000001000100111010010",
  "01111111010000010101000",
  "00000000000000000000000"
];
function textPaths(text: string, x: number, y: number, size: number) {
  let advance = 0;
  const paths = [...text].map(char => {
    const glyph = outlines.glyphs[char as keyof typeof outlines.glyphs];
    const path = `<path transform="translate(${advance} 0)" d="${glyph.path}"/>`;
    advance += glyph.advance; return path;
  }).join("");
  return `<g fill="#172b28" transform="translate(${x} ${y}) scale(${size/outlines.unitsPerEm} ${-size/outlines.unitsPerEm})">${paths}</g>`;
}
// Colored edges expose unintended crops; vector text/QR exercise fine detail and transparency.
export async function editorImage(width: number, height: number, transparent = false) {
  const unit = Math.max(2, Math.floor(Math.min(width,height)/110));
  const qrSize=(qr.length+8)*unit;
  const cells=qr.flatMap((row,y)=>[...row].flatMap((c,x)=>c==="1" ? [`<rect x="${(x+4)*unit}" y="${(y+4)*unit}" width="${unit}" height="${unit}"/>`] : [])).join("");
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}">
    ${transparent ? "" : '<rect width="100%" height="100%" fill="#fff"/>'}
    <rect width="100%" height="12" fill="#16804b"/><rect y="${height-12}" width="100%" height="12" fill="#8436a0"/>
    <rect width="12" height="100%" fill="#c92b2b"/><rect x="${width-12}" width="12" height="100%" fill="#2459b2"/>
    ${textPaths("LOCAL TEST",30,Math.min(width,height)*0.15,Math.min(width,height)*0.07)}
    ${textPaths("914 555 0123",30,Math.min(width,height)*0.22,Math.min(width,height)*0.035)}
    ${textPaths("Fine print stays in the original",30,height-35,Math.min(width,height)*0.016)}
    <g transform="translate(${width-qrSize-25} ${height-qrSize-65})"><rect width="${qrSize}" height="${qrSize}" fill="white"/><g fill="black">${cells}</g></g>
  </svg>`;
  return sharp(Buffer.from(svg)).png().toBuffer();
}
